def deployment_logs(deployment_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "deployment_logs"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, deployment_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "deployment_id": deployment_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(deployment_id, str) or not deployment_id.strip():
        _append_request_log("VALIDATION_ERROR", deployment_id=deployment_id)
        return _err("VALIDATION_ERROR", "deployment_id is required and must be a non-empty string.", field="deployment_id")
    deployment_id = deployment_id.strip()

    if limit is None:
        limit = 2000
    if not isinstance(limit, int) or not (1 <= limit <= 10000):
        _append_request_log("VALIDATION_ERROR", deployment_id=deployment_id)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 10000.", field="limit")

    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _append_request_log("VALIDATION_ERROR", deployment_id=deployment_id)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
        cursor = cursor.strip()

    deployments = _load("deployments.json")
    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(deployments, list):
        deployments = []
    if not isinstance(services, list):
        services = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(accounts, list):
        accounts = []

    # Find deployment by internal id or upstream railway_deployment_id
    dep = None
    for d in deployments:
        if isinstance(d, dict) and (d.get("id") == deployment_id or d.get("railway_deployment_id") == deployment_id):
            dep = d
            break
    if dep is None:
        _append_request_log("NOT_FOUND", deployment_id=deployment_id)
        return _err("NOT_FOUND", "Deployment does not exist.", deployment_id=deployment_id)

    # Resolve account context via service->project->account
    svc = None
    for s in services:
        if isinstance(s, dict) and s.get("id") == dep.get("service_id"):
            svc = s
            break
    if svc is None:
        _append_request_log("NOT_FOUND", deployment_id=deployment_id)
        return _err("NOT_FOUND", "Deployment exists but owning service was not found.", deployment_id=deployment_id)

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == svc.get("project_id"):
            prj = p
            break
    if prj is None:
        _append_request_log("NOT_FOUND", deployment_id=deployment_id)
        return _err("NOT_FOUND", "Deployment exists but owning project was not found.", deployment_id=deployment_id)

    account_id = prj.get("account_id")
    # Ambient auth: allow if any active account exists; otherwise unauthorized
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id, deployment_id=deployment_id)
        return _err("UNAUTHORIZED", "Not authorized to access deployment logs (no active account token available).", account_id=account_id)

    if not isinstance(dep.get("logs"), list):
        dep_logs = []
    else:
        dep_logs = dep.get("logs")

    # Cursor is opaque; implement as "offset:<int>" or "idx:<int>" and also accept plain integer offsets.
    start = 0
    if cursor is not None:
        parsed = None
        if cursor.isdigit():
            parsed = int(cursor)
        else:
            for pref in ("offset:", "idx:", "cursor:"):
                if cursor.startswith(pref):
                    rest = cursor[len(pref):]
                    if rest.isdigit():
                        parsed = int(rest)
                    break
        if parsed is None or parsed < 0:
            _append_request_log("VALIDATION_ERROR", account_id=account_id, deployment_id=deployment_id, extra={"cursor": cursor})
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        start = parsed

    total = len(dep_logs)
    if start > total:
        start = total
    end = min(total, start + limit)
    items = dep_logs[start:end]

    next_cursor = None
    has_more = end < total
    if has_more:
        next_cursor = f"offset:{end}"

    _append_request_log("OK", account_id=account_id, deployment_id=deployment_id, extra={"returned": len(items), "total": total, "has_more": has_more})
    return {
        "deployment_id": dep.get("id"),
        "railway_deployment_id": dep.get("railway_deployment_id"),
        "service_id": dep.get("service_id"),
        "railway_environment_id": dep.get("railway_environment_id"),
        "status": dep.get("status"),
        "logs": items,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
        },
    }

