def domain_list(service_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "domain_list"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is required and must be a non-empty string.", field="service_id")
    service_id = service_id.strip()

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 100):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")

    # Cursor: accept opaque strings. If it matches our scheme "idx:<int>", use it; else start from 0.
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _append_request_log("VALIDATION_ERROR", service_id=service_id)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
        c = cursor.strip()
        if c.startswith("idx:"):
            try:
                start = int(c.split(":", 1)[1])
            except ValueError:
                start = 0
        elif c.isdigit():
            try:
                start = int(c)
            except ValueError:
                start = 0
        else:
            start = 0
        if start < 0:
            start = 0

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list): services = []
    if not isinstance(projects, list): projects = []
    if not isinstance(accounts, list): accounts = []

    svc = next((s for s in services if isinstance(s, dict) and s.get("id") == service_id), None)
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if proj is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Parent project does not exist.", project_id=svc.get("project_id"))

    account_id = proj.get("account_id")
    if not any(isinstance(a, dict) and a.get("id") == account_id for a in accounts):
        _append_request_log("UNAUTHORIZED", service_id=service_id)
        return _err("UNAUTHORIZED", "You do not have access to this service.", service_id=service_id)

    doms = svc.get("domains")
    if not isinstance(doms, list):
        doms = []

    if start > len(doms):
        start = len(doms)

    page = doms[start:start + limit]
    next_cursor = None
    if start + limit < len(doms):
        next_cursor = f"idx:{start + limit}"

    _append_request_log("ok", account_id=account_id, service_id=service_id)

    return {
        "service_id": service_id,
        "domains": page,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "total": len(doms),
        "has_more": next_cursor is not None,
    }

def domain_create(service_id, domain, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "domain_create"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is required and must be a non-empty string.", field="service_id")
    service_id = service_id.strip()

    if not isinstance(domain, str) or not domain.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "domain is required and must be a non-empty string.", field="domain")
    domain = domain.strip().lower()

    # Relaxed validation: accept any hostname-like string, including those without dots, to match observed calls.
    # Still reject obviously invalid whitespace.
    if any(ch.isspace() for ch in domain) or len(domain) > 253:
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "domain must be a valid domain name.", field="domain")

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list): services = []
    if not isinstance(projects, list): projects = []
    if not isinstance(accounts, list): accounts = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    if svc.get("status") in ("deleting", "deleted"):
        _append_request_log("CONFLICT", service_id=service_id)
        return _err("CONFLICT", "Service is deleting/deleted; domains cannot be modified.", service_status=svc.get("status"))

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if proj is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Parent project does not exist.", project_id=svc.get("project_id"))

    account_id = proj.get("account_id")
    if not any(isinstance(a, dict) and a.get("id") == account_id for a in accounts):
        _append_request_log("UNAUTHORIZED", service_id=service_id)
        return _err("UNAUTHORIZED", "You do not have permission to modify this service.", service_id=service_id)

    # Domain global uniqueness within account
    # Precompute project->account_id
    proj_to_acct = {p.get("id"): p.get("account_id") for p in projects if isinstance(p, dict)}
    for s in services:
        if not isinstance(s, dict):
            continue
        p_acc = proj_to_acct.get(s.get("project_id"))
        if p_acc != account_id:
            continue
        ds = s.get("domains")
        if not isinstance(ds, list):
            continue
        for d in ds:
            if not isinstance(d, dict):
                continue
            if str(d.get("hostname", "")).lower() == domain:
                if s.get("id") == service_id:
                    _append_request_log("CONFLICT", account_id=account_id, service_id=service_id)
                    return _err("CONFLICT", "Domain is already attached to this service.", domain=domain)
                _append_request_log("CONFLICT", account_id=account_id, service_id=service_id)
                return _err("CONFLICT", "Domain is not available to be claimed (already in use within this account).", domain=domain)

    doms = svc.get("domains")
    if not isinstance(doms, list):
        doms = []

    # Create domain entry
    dom_entry = {
        "id": "dom_" + uuid.uuid4().hex,
        "hostname": domain,
        "custom": True,
        "created_at": _now(),
        "updated_at": _now(),
    }
    doms.append(dom_entry)
    svc["domains"] = doms
    svc["updated_at"] = _now()
    services[svc_idx] = svc
    _save("services.json", services)

    _append_request_log("ok", account_id=account_id, service_id=service_id)

    return {"service_id": service_id, "domain": dom_entry}

def domain_check(domain, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "domain_check"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(domain, str) or not domain.strip():
        _append_request_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "domain is required and must be a non-empty string.", field="domain")

    raw = domain.strip()
    norm = raw.lower()
    if any(ch.isspace() for ch in norm) or len(norm) > 253:
        _append_request_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "domain must be a non-empty token without spaces and at most 253 characters.", field="domain")

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list):
        services = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(accounts, list):
        accounts = []

    # Ambient auth context: choose an account with an active token if possible; otherwise, any account.
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("token_status") == "active" and isinstance(a.get("id"), str)]
    if active_accounts:
        context_account_id = active_accounts[0].get("id")
    else:
        # If the store has no active token at all, domain check is forbidden.
        context_account_id = None
        _append_request_log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account is not authorized to perform domain checks (no active token).")

    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}

    claimed = None
    for s in services:
        if not isinstance(s, dict):
            continue
        prj = proj_by_id.get(s.get("project_id"))
        if not isinstance(prj, dict):
            continue
        if prj.get("account_id") != context_account_id:
            continue
        doms = s.get("domains")
        if not isinstance(doms, list):
            continue
        for d in doms:
            if not isinstance(d, dict):
                continue
            hn = d.get("hostname")
            if isinstance(hn, str) and hn.lower() == norm:
                claimed = {"service_id": s.get("id"), "domain_id": d.get("id"), "hostname": hn}
                break
        if claimed:
            break

    if claimed:
        # Must return data (availability result), not an error.
        _append_request_log("OK", account_id=context_account_id, extra={"available": False, "domain": norm, "claimed_by": claimed})
        return {
            "domain": norm,
            "available": False,
            "reason": "already_claimed_within_account",
            "claimed_by": claimed,
        }

    _append_request_log("OK", account_id=context_account_id, extra={"available": True, "domain": norm})
    return {"domain": norm, "available": True}

def domain_update(service_id, domain, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "domain_update"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip() or not re.match(r"^rwy_svc_[0-9A-Z]{4}.*$", service_id.strip()):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is invalid.", field="service_id")
    service_id = service_id.strip()

    if not isinstance(domain, dict):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "domain must be an object.", field="domain")

    allowed_domain_keys = {"id", "target_port", "https_redirect"}
    extra_keys = set(domain.keys()) - allowed_domain_keys
    if extra_keys:
        _append_request_log("VALIDATION_ERROR", service_id=service_id, extra={"extra_keys": sorted(extra_keys)})
        return _err("VALIDATION_ERROR", "Unrecognized fields in domain object.", fields=sorted(extra_keys))

    dom_id = domain.get("id")
    if not isinstance(dom_id, str) or not dom_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "domain.id is required and must be a non-empty string.", field="domain.id")
    dom_id = dom_id.strip()

    if "target_port" in domain:
        tp = domain.get("target_port")
        if not isinstance(tp, int) or not (1 <= tp <= 65535):
            _append_request_log("VALIDATION_ERROR", service_id=service_id)
            return _err("VALIDATION_ERROR", "domain.target_port must be an integer between 1 and 65535.", field="domain.target_port")
    if "https_redirect" in domain and not isinstance(domain.get("https_redirect"), bool):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "domain.https_redirect must be a boolean.", field="domain.https_redirect")

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list):
        services = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(accounts, list):
        accounts = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    # Disallow changes to deleted services
    if svc.get("status") == "deleted":
        _append_request_log("INVALID_TRANSITION", service_id=service_id)
        return _err("INVALID_TRANSITION", "Deleted services are immutable; domain updates are not allowed.", service_id=service_id)

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == svc.get("project_id"):
            prj = p
            break
    account_id = prj.get("account_id") if isinstance(prj, dict) else None

    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id, service_id=service_id)
        return _err("UNAUTHORIZED", "Not authorized to update domains (no active account token available).", account_id=account_id)

    doms = svc.get("domains")
    if not isinstance(doms, list):
        doms = []

    dom_idx = None
    dom_row = None
    for j, d in enumerate(doms):
        if isinstance(d, dict) and d.get("id") == dom_id:
            dom_idx = j
            dom_row = d
            break

    if dom_row is None:
        _append_request_log("NOT_FOUND", account_id=account_id, service_id=service_id, extra={"domain_id": dom_id})
        return _err("NOT_FOUND", "Domain not found on this service.", service_id=service_id, domain_id=dom_id)

    # hostname is immutable: ensure we don't accept a hostname field even if present (already blocked by additionalProperties)
    updated = dict(dom_row)
    if "target_port" in domain:
        updated["target_port"] = domain.get("target_port")
    if "https_redirect" in domain:
        updated["https_redirect"] = domain.get("https_redirect")

    now = _now()
    if "updated_at" in updated or True:
        updated["updated_at"] = now

    doms[dom_idx] = updated
    svc["domains"] = doms
    svc["updated_at"] = now
    services[svc_idx] = svc
    _save("services.json", services)

    _append_request_log("OK", account_id=account_id, service_id=service_id, extra={"domain_id": dom_id})
    return {"service_id": service_id, "domain": updated}

def domain_delete(service_id, domain_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "domain_delete"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip() or not re.match(r"^rwy_svc_[0-9A-Z]{4}.*$", service_id.strip()):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is missing or invalid.", field="service_id")
    service_id = service_id.strip()

    if not isinstance(domain_id, str) or not domain_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "domain_id is missing or invalid.", field="domain_id")
    domain_id = domain_id.strip()

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list):
        services = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(accounts, list):
        accounts = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    if svc.get("status") == "deleted":
        _append_request_log("INVALID_TRANSITION", service_id=service_id)
        return _err("INVALID_TRANSITION", "Deleted services are immutable; domain deletions are not allowed.", service_id=service_id)

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == svc.get("project_id"):
            prj = p
            break
    account_id = prj.get("account_id") if isinstance(prj, dict) else None
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id, service_id=service_id)
        return _err("UNAUTHORIZED", "Not authorized to delete domains (no active account token available).", account_id=account_id)

    doms = svc.get("domains")
    if not isinstance(doms, list):
        doms = []

    removed = None
    new_doms = []
    for d in doms:
        if removed is None and isinstance(d, dict) and d.get("id") == domain_id:
            removed = d
            continue
        new_doms.append(d)

    if removed is None:
        _append_request_log("NOT_FOUND", account_id=account_id, service_id=service_id, extra={"domain_id": domain_id})
        return _err("NOT_FOUND", "domain_id is not present on that service.", service_id=service_id, domain_id=domain_id)

    now = _now()
    svc["domains"] = new_doms
    svc["updated_at"] = now
    services[svc_idx] = svc
    _save("services.json", services)

    _append_request_log("OK", account_id=account_id, service_id=service_id, extra={"domain_id": domain_id})
    return {"service_id": service_id, "deleted": True, "domain": removed}

def project_list(account_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, credential_id=None, account_id=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": ts,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "account_id": account_id,
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint = "project_list"

    if not isinstance(account_id, str) or not re.match(r"^rwy_acct_[0-9A-Z]{4}.*$", account_id):
        _log(endpoint, "VALIDATION_ERROR", started=started)
        return _err("VALIDATION_ERROR", "account_id is missing or invalid.")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleting", "deleted"):
            _log(endpoint, "VALIDATION_ERROR", started=started, account_id=account_id)
            return _err("VALIDATION_ERROR", "status is invalid.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(endpoint, "VALIDATION_ERROR", started=started, account_id=account_id)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "name"):
        _log(endpoint, "VALIDATION_ERROR", started=started, account_id=account_id)
        return _err("VALIDATION_ERROR", "sort is invalid.")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log(endpoint, "VALIDATION_ERROR", started=started, account_id=account_id)
        return _err("VALIDATION_ERROR", "order is invalid.")

    # Authenticate ambiently: must have active token for this account
    accounts = _load("railway_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id and a.get("token_status") == "active" and a.get("api_token_ciphertext"):
            acct = a
            break
    if not acct:
        _log(endpoint, "UNAUTHORIZED", started=started, account_id=account_id)
        return _err("UNAUTHORIZED", "You don’t have access to the account.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Business rule: return all projects where account matches active account and status != deleted
    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("account_id") != account_id:
            continue
        if p.get("status") == "deleted":
            continue
        if status is not None and p.get("status") != status:
            continue
        rows.append(p)

    # Cursor: opaque base64 of integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log(endpoint, "VALIDATION_ERROR", credential_id=acct.get("id"), started=started, account_id=account_id)
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(decoded.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("account_id") != account_id:
                _log(endpoint, "VALIDATION_ERROR", credential_id=acct.get("id"), started=started, account_id=account_id)
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                raise ValueError()
        except Exception:
            _log(endpoint, "VALIDATION_ERROR", credential_id=acct.get("id"), started=started, account_id=account_id)
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    def _sort_key(p):
        v = p.get(sort)
        if sort in ("created_at", "updated_at"):
            # ISO timestamps sort lexicographically when in Z/UTC; fallback empty
            return v or ""
        return (v or "").lower()

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "account_id": account_id, "offset": next_offset, "sort": sort, "order": order, "status": status}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(endpoint, "OK", credential_id=acct.get("id"), started=started, account_id=account_id)
    return {
        "projects": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "status": status,
        },
    }

def project_info(project_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, account_id=None, project_id=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": ts,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "account_id": account_id,
            "project_id": project_id,
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint = "project_info"

    if not isinstance(project_id, str) or not re.match(r"^rwy_prj_[0-9A-Z]{4}.*$", project_id):
        _log(endpoint, "VALIDATION_ERROR", started=started)
        return _err("VALIDATION_ERROR", "project_id is missing or invalid.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    services = _load("services.json")
    if not isinstance(services, list):
        services = []
    accounts = _load("railway_accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            prj = p
            break
    if not prj:
        _log(endpoint, "NOT_FOUND", started=started, project_id=project_id)
        return _err("NOT_FOUND", "Project not found.")

    account_id = prj.get("account_id")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id and a.get("token_status") == "active" and a.get("api_token_ciphertext"):
            acct = a
            break
    if not acct:
        _log(endpoint, "UNAUTHORIZED", started=started, project_id=project_id, account_id=account_id)
        return _err("UNAUTHORIZED", "You don’t have permission to read the project.")

    # Include associated structure needed to navigate environments and services
    prj_services = []
    for s in services:
        if not isinstance(s, dict):
            continue
        if s.get("project_id") != project_id:
            continue
        prj_services.append({
            "id": s.get("id"),
            "railway_service_id": s.get("railway_service_id"),
            "name": s.get("name"),
            "service_type": s.get("service_type"),
            "status": s.get("status"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at"),
        })

    result = dict(prj)
    if "environments" not in result or not isinstance(result.get("environments"), list):
        result["environments"] = []
    result["services"] = prj_services

    _log(endpoint, "OK", credential_id=acct.get("id"), started=started, project_id=project_id, account_id=account_id)
    return {"project": result}

def project_create(account_id, name, description=None, **_extra):
    import json, os, datetime, re, time, uuid, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # ULID-like opaque id; keep deterministic-ish prefix for validation patterns
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    # --- usage / rate limit logging helpers (best-effort based on store presence) ---
    def _find_usage_file():
        # If a usage/audit collection exists, use it. Prefer common names.
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "railway_usage.json", "railway_request_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _rate_limits_ok(logs, acct_id):
        # Conservative defaults; enforce if we have logs collection
        now = datetime.datetime.utcnow()
        # rate: 60 req/min per account
        window = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if r.get("account_id") != acct_id:
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window:
                recent += 1
        if recent >= 60:
            return False, ("RATE_LIMIT", "Rate limit exceeded for this account (60 requests/min).")
        # quota: 1000 req/day per account
        day = now - datetime.timedelta(days=1)
        daily = 0
        for r in logs:
            if r.get("account_id") != acct_id:
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= day:
                daily += 1
        if daily >= 1000:
            return False, ("QUOTA_EXCEEDED", "Daily request quota exceeded for this account (1000 requests/day).")
        return True, None

    def _log_call(endpoint, acct_id, status, latency_ms, extra=None):
        fn = _find_usage_file()
        if not fn:
            return
        logs = _load(fn)
        row = {
            "id": _gen_id("rwy_req"),
            "endpoint": endpoint,
            "account_id": acct_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "ts": _now(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fn, logs)

    t0 = time.time()

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^rwy_acct_[0-9A-Z]{4}.*$", account_id):
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
    if not isinstance(name, str) or len(name.strip()) < 1:
        return _err("VALIDATION_ERROR", "name is required and must be non-empty.", field="name")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")

    accounts = _load("railway_accounts.json")
    projects = _load("projects.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        # Ambiant auth: if account doesn't exist, treat as not found/unauthorized for create.
        _log_call("project_create", account_id, "UNAUTHORIZED", (time.time() - t0) * 1000.0)
        return _err("UNAUTHORIZED", "You don’t have permission to create projects in that account.")

    # Require an active token to perform upstream-acting operations
    if acct.get("token_status") != "active" or not acct.get("api_token_ciphertext"):
        _log_call("project_create", account_id, "UNAUTHORIZED", (time.time() - t0) * 1000.0)
        return _err("UNAUTHORIZED", "No active API token configured for this account.")

    # Enforce rate/quota if we have logs
    usage_file = _find_usage_file()
    if usage_file:
        logs = _load(usage_file)
        ok, why = _rate_limits_ok(logs, account_id)
        if not ok:
            code, msg = why
            _log_call("project_create", account_id, code, (time.time() - t0) * 1000.0)
            return _err(code, msg)

    # Enforce unique(account_id, name)
    for p in projects:
        if p.get("account_id") == account_id and p.get("name") == name and p.get("status") != "deleted":
            _log_call("project_create", account_id, "CONFLICT", (time.time() - t0) * 1000.0)
            return _err("CONFLICT", "A project with this name already exists in the account.", field="name")

    # Per-account project count quota (conservative)
    active_count = sum(1 for p in projects if p.get("account_id") == account_id and p.get("status") != "deleted")
    if active_count >= 100:
        _log_call("project_create", account_id, "QUOTA_EXCEEDED", (time.time() - t0) * 1000.0)
        return _err("QUOTA_EXCEEDED", "Project quota exceeded for this account (100).")

    # Create upstream project id placeholder (opaque)
    railway_project_id = _gen_id("prj").replace("prj_", "railway_prj_")

    now = _now()
    row = {
        "id": _gen_id("rwy_prj"),
        "account_id": account_id,
        "railway_project_id": railway_project_id,
        "name": name,
        "description": description,
        "status": "active",
        # Seed environments with at least one default environment as initial cache
        "environments": [
            {"railway_environment_id": _gen_id("env").replace("env_", "railway_env_"), "name": "production", "is_default": True}
        ],
        "created_at": now,
        "updated_at": now,
    }

    # Enforce unique(account_id, railway_project_id) and unique(account_id, name) hard
    if any(p.get("account_id") == account_id and p.get("railway_project_id") == railway_project_id for p in projects):
        # Extremely unlikely; regenerate once
        railway_project_id = _gen_id("prj").replace("prj_", "railway_prj_")
        row["railway_project_id"] = railway_project_id
        if any(p.get("account_id") == account_id and p.get("railway_project_id") == railway_project_id for p in projects):
            _log_call("project_create", account_id, "CONFLICT", (time.time() - t0) * 1000.0)
            return _err("CONFLICT", "Could not allocate a unique upstream project id. Please retry.")

    projects.append(row)
    _save("projects.json", projects)

    _log_call("project_create", account_id, "OK", (time.time() - t0) * 1000.0)
    return {"project": row}

def project_delete(project_id, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _find_usage_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "railway_usage.json", "railway_request_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _rate_limits_ok(logs, acct_id):
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if r.get("account_id") != acct_id:
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window:
                recent += 1
        if recent >= 60:
            return False, ("RATE_LIMIT", "Rate limit exceeded for this account (60 requests/min).")
        day = now - datetime.timedelta(days=1)
        daily = 0
        for r in logs:
            if r.get("account_id") != acct_id:
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= day:
                daily += 1
        if daily >= 1000:
            return False, ("QUOTA_EXCEEDED", "Daily request quota exceeded for this account (1000 requests/day).")
        return True, None

    def _log_call(endpoint, acct_id, status, latency_ms, extra=None):
        fn = _find_usage_file()
        if not fn:
            return
        logs = _load(fn)
        row = {
            "id": _gen_id("rwy_req"),
            "endpoint": endpoint,
            "account_id": acct_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "ts": _now(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fn, logs)

    t0 = time.time()

    if not isinstance(project_id, str) or not re.match(r"^rwy_prj_[0-9A-Z]{4}.*$", project_id):
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")

    accounts = _load("railway_accounts.json")
    projects = _load("projects.json")
    services = _load("services.json")

    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj:
        _log_call("project_delete", None, "NOT_FOUND", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    acct_id = proj.get("account_id")
    acct = next((a for a in accounts if a.get("id") == acct_id), None)
    if not acct or acct.get("token_status") != "active" or not acct.get("api_token_ciphertext"):
        _log_call("project_delete", acct_id, "UNAUTHORIZED", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
        return _err("UNAUTHORIZED", "You don’t have permission to delete this project.")

    usage_file = _find_usage_file()
    if usage_file:
        logs = _load(usage_file)
        ok, why = _rate_limits_ok(logs, acct_id)
        if not ok:
            code, msg = why
            _log_call("project_delete", acct_id, code, (time.time() - t0) * 1000.0, extra={"project_id": project_id})
            return _err(code, msg)

    status = proj.get("status")
    if status in ("deleting", "deleted"):
        _log_call("project_delete", acct_id, "CONFLICT", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
        return _err("CONFLICT", f"Project is already {status}.", project_status=status)

    if status != "active":
        _log_call("project_delete", acct_id, "INVALID_TRANSITION", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
        return _err("INVALID_TRANSITION", "Project cannot be deleted from its current status.", from_status=status, to_status="deleting")

    # Transition project to deleting immediately
    now = _now()
    proj["status"] = "deleting"
    proj["updated_at"] = now

    # Transition services under project to deleting as well (active/restarting -> deleting)
    changed_services = 0
    for s in services:
        if s.get("project_id") != project_id:
            continue
        s_status = s.get("status")
        if s_status in ("active", "restarting"):
            s["status"] = "deleting"
            s["updated_at"] = now
            changed_services += 1
        elif s_status == "deleting":
            pass
        elif s_status == "deleted":
            pass
        else:
            # Unknown state; treat as invalid transition rather than partial delete
            _log_call("project_delete", acct_id, "INVALID_TRANSITION", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
            return _err("INVALID_TRANSITION", "A contained service is in an invalid state for deletion.", service_id=s.get("id"), service_status=s_status)

    # Persist project + services updates
    _save("projects.json", projects)
    if changed_services:
        _save("services.json", services)

    # Upstream confirmation is not available offline; remain in deleting.
    _log_call("project_delete", acct_id, "OK", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
    return {"project": proj}

