def service_list(project_id, status=None, service_type=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _find_usage_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "railway_usage.json", "railway_request_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _rate_limits_ok(logs, acct_id):
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if r.get("account_id") != acct_id:
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window:
                recent += 1
        if recent >= 60:
            return False, ("RATE_LIMIT", "Rate limit exceeded for this account (60 requests/min).")
        day = now - datetime.timedelta(days=1)
        daily = 0
        for r in logs:
            if r.get("account_id") != acct_id:
                continue
            ts = r.get("ts") or r.get("timestamp") or r.get("created_at")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= day:
                daily += 1
        if daily >= 1000:
            return False, ("QUOTA_EXCEEDED", "Daily request quota exceeded for this account (1000 requests/day).")
        return True, None

    def _log_call(endpoint, acct_id, status_code, latency_ms, extra=None):
        fn = _find_usage_file()
        if not fn:
            return
        logs = _load(fn)
        row = {
            "id": _gen_id("rwy_req"),
            "endpoint": endpoint,
            "account_id": acct_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "ts": _now(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fn, logs)

    def _parse_cursor(cur):
        if not cur:
            return None
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"==").decode("utf-8")
            if raw.startswith("idx:"):
                return int(raw.split(":", 1)[1])
        except Exception:
            return None
        return None

    def _make_cursor(idx):
        raw = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()

    if not isinstance(project_id, str) or not re.match(r"^rwy_prj_[0-9A-Z]{4}.*$", project_id):
        return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")

    valid_status = {"active", "restarting", "deleting", "deleted"}
    valid_type = {"repo", "image", "template", "database"}
    valid_sort = {"created_at", "updated_at", "name"}
    valid_order = {"asc", "desc"}

    if status is not None and (not isinstance(status, str) or status not in valid_status):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status", allowed=sorted(valid_status))
    if service_type is not None and (not isinstance(service_type, str) or service_type not in valid_type):
        return _err("VALIDATION_ERROR", "Invalid service_type filter.", field="service_type", allowed=sorted(valid_type))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in valid_sort:
        return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort", allowed=sorted(valid_sort))
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in valid_order:
        return _err("VALIDATION_ERROR", "Invalid order.", field="order", allowed=sorted(valid_order))

    accounts = _load("railway_accounts.json")
    projects = _load("projects.json")
    services = _load("services.json")

    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj or proj.get("status") == "deleted":
        _log_call("service_list", None, "NOT_FOUND", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    acct_id = proj.get("account_id")
    acct = next((a for a in accounts if a.get("id") == acct_id), None)
    if not acct or acct.get("token_status") != "active" or not acct.get("api_token_ciphertext"):
        _log_call("service_list", acct_id, "UNAUTHORIZED", (time.time() - t0) * 1000.0, extra={"project_id": project_id})
        return _err("UNAUTHORIZED", "You don’t have access to the project.")

    usage_file = _find_usage_file()
    if usage_file:
        logs = _load(usage_file)
        ok, why = _rate_limits_ok(logs, acct_id)
        if not ok:
            code, msg = why
            _log_call("service_list", acct_id, code, (time.time() - t0) * 1000.0, extra={"project_id": project_id})
            return _err(code, msg)

    # Filter to project
    rows = [s for s in services if s.get("project_id") == project_id]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]
    if service_type is not None:
        rows = [s for s in rows if s.get("service_type") == service_type]

    # Sort
    reverse = (order == "desc")

    def _key(s):
        v = s.get(sort)
        if sort in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort == "name":
            return (v or "").lower() if isinstance(v, str) else ""
        return v

    rows.sort(key=_key, reverse=reverse)

    # Pagination by index cursor
    start = _parse_cursor(cursor)
    if start is None:
        start = 0
    if start < 0:
        return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    total = len(rows)
    page = rows[start:start + limit]
    next_idx = start + len(page)
    has_more = next_idx < total
    next_cursor = _make_cursor(next_idx) if has_more else None

    _log_call(
        "service_list",
        acct_id,
        "OK",
        (time.time() - t0) * 1000.0,
        extra={"project_id": project_id, "returned": len(page), "total": total},
    )
    return {
        "services": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
    }

