        nonlocal used_account_id
        accounts = _load("railway_accounts.json")
        active_accounts = [a for a in accounts if a.get("token_status") == "active" and a.get("api_token_ciphertext")]
        if not active_accounts:
            return None, _err("UNAUTHORIZED", "No active Railway account token is configured.")
        used_account_id = active_accounts[0].get("id")

        # simple per-account rate limit: 120 req/min
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if r.get("account_id") != used_account_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                count += 1
        if count >= 120:
            return used_account_id, _err("QUOTA_EXCEEDED", "Rate limit exceeded for this account.", limit_per_minute=120)
        return used_account_id, None

    try:
        if not isinstance(service_id, str):
            used_account_id, qerr = _check_quota()
            if qerr:
                _log("error", qerr["error"]["code"])
                return qerr
            verr = _err("VALIDATION_ERROR", "service_id must be a string.")
            _log("error", "VALIDATION_ERROR")
            return verr
        if not re.match(r"^rwy_svc_[0-9A-Z]+$", service_id):
            used_account_id, qerr = _check_quota()
            if qerr:
                _log("error", qerr["error"]["code"])
                return qerr
            verr = _err("VALIDATION_ERROR", "service_id is malformed.")
            _log("error", "VALIDATION_ERROR")
            return verr

        used_account_id, qerr = _check_quota()
        if qerr:
            _log("error", qerr["error"]["code"])
            return qerr

        services = _load("services.json")
        svc = next((s for s in services if s.get("id") == service_id), None)
        if not svc:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Service not found.")

        projects = _load("projects.json")
        proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
        if not proj:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Service project not found.")
        if proj.get("account_id") != used_account_id:
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "You do not have access to this service.")

        # Return the stored record; do not fabricate extra fields.
        _log("ok")
        return {"service": svc}
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

