            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip() or not re.match(r"^rwy_svc_[0-9A-Z]+$", service_id.strip()):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is malformed.", field="service_id")
    service_id = service_id.strip()

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.", field="name")
    if config is not None and not isinstance(config, dict):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "config must be an object when provided.", field="config")
    if source is not None and not isinstance(source, dict):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "source must be an object when provided.", field="source")

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list): services = []
    if not isinstance(projects, list): projects = []
    if not isinstance(accounts, list): accounts = []

    idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            idx = i
            svc = s
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    if svc.get("status") in ("deleting", "deleted"):
        _append_request_log("CONFLICT", service_id=service_id)
        return _err("CONFLICT", "Service is deleting/deleted and cannot be updated.", service_status=svc.get("status"))

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if proj is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Parent project does not exist.", project_id=svc.get("project_id"))

    account_id = proj.get("account_id")
    if not any(isinstance(a, dict) and a.get("id") == account_id for a in accounts):
        _append_request_log("UNAUTHORIZED", service_id=service_id)
        return _err("UNAUTHORIZED", "You do not have permission to modify this service.", service_id=service_id)

    # If renaming, enforce unique(project_id, name)
    if name is not None:
        new_name = name.strip()
        for s in services:
            if not isinstance(s, dict):
                continue
            if s.get("id") != service_id and s.get("project_id") == svc.get("project_id") and s.get("name") == new_name:
                _append_request_log("CONFLICT", account_id=account_id, service_id=service_id)
                return _err("CONFLICT", "A service with this name already exists in the project.", project_id=svc.get("project_id"), name=new_name)
        svc["name"] = new_name

    if config is not None:
        svc["config"] = config

    if source is not None:
        svc["source"] = source

    svc["updated_at"] = _now()
    services[idx] = svc
    _save("services.json", services)

    _append_request_log("ok", account_id=account_id, service_id=service_id)
    return {"service": svc}

def service_delete(service_id, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}{''.join(random.choice(alphabet) for _ in range(16))}"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    t0 = time.time()
    status_code = "ok"
    used_account_id = None

    # Load store
    accounts = _load("railway_accounts.json")
    projects = _load("projects.json")
    services = _load("services.json")
    deployments = _load("deployments.json")

    # Resolve an authenticated working context: any account with active token
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("token_status") == "active" and a.get("api_token_ciphertext")]
    if not active_accounts:
        status_code = "UNAUTHORIZED"
        latency_ms = int((time.time() - t0) * 1000)
        # No request log collection declared; do not fabricate it.
        return _err("UNAUTHORIZED", "No active Railway account token is configured.")

    # Validate inputs
    if not isinstance(service_id, str) or not re.match(r"^rwy_svc_[0-9A-Z]+$", service_id):
        status_code = "VALIDATION_ERROR"
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "service_id is missing or malformed.", field="service_id")

    # Find service row
    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc_idx = i
            svc = s
            break
    if svc is None:
        status_code = "NOT_FOUND"
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Service not found.", service_id=service_id)

    # Validate FK project exists and map to account
    project_id = svc.get("project_id")
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if proj is None:
        status_code = "NOT_FOUND"
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Parent project for service not found.", project_id=project_id)

    account_id = proj.get("account_id")
    used_account_id = account_id

    # Authorize: ensure there exists an active token account matching the service's account_id
    if not any(a.get("id") == account_id for a in active_accounts):
        status_code = "UNAUTHORIZED"
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Active token does not permit managing this service.", service_id=service_id)

    # Enforce lifecycle transitions
    cur = svc.get("status")
    allowed = {"active": ["deleting"], "restarting": ["deleting"], "deleting": ["deleted"], "deleted": []}
    if cur not in allowed:
        status_code = "CONFLICT"
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", "Service has an unknown status and cannot be deleted.", status=cur)

    now = _now()
    svc_before = json.loads(json.dumps(svc))

    if cur == "deleted":
        # Mutation must have effect; already deleted => conflict (cannot delete due to current state)
        status_code = "CONFLICT"
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", "Service is already deleted.", service_id=service_id, status=cur)

    if cur in ("active", "restarting"):
        # Transition to deleting and clear config scoped to service (keep domains/proxies/vars/volumes arrays but empty them)
        svc["status"] = "deleting"
        svc["domains"] = []
        svc["tcp_proxies"] = []
        svc["variables"] = []
        svc["volumes"] = []
        svc["config"] = svc.get("config")  # config may be kept or cleared; rule says delete configuration scoped to it
        svc["config"] = None
        svc["updated_at"] = now

        # Also mark all deployments for this service as cancelled if in-flight (queued/building/deploying)
        changed_any_depl = False
        for d in deployments:
            if not isinstance(d, dict):
                continue
            if d.get("service_id") != service_id:
                continue
            st = d.get("status")
            if st in ("queued", "building", "deploying"):
                # Legal transitions to cancelled
                d["status"] = "cancelled"
                d["finished_at"] = now
                d["updated_at"] = now
                if d.get("started_at") is None:
                    d["started_at"] = d.get("created_at") or now
                changed_any_depl = True

        # Persist
        services[svc_idx] = svc
        _save("services.json", services)
        if changed_any_depl:
            _save("deployments.json", deployments)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "service": svc,
            "previous": svc_before,
            "deletion": {
                "acknowledged": True,
                "status": "deleting",
                "service_id": service_id,
                "updated_at": now
            },
            "meta": {"latency_ms": latency_ms}
        }

    # cur == "deleting": allow finalize to deleted (as "confirmed")
    if cur == "deleting":
        svc["status"] = "deleted"
        svc["updated_at"] = now

        # Ensure no further mutations possible; keep arrays as-is (already cleared typically)
        services[svc_idx] = svc
        _save("services.json", services)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "service": svc,
            "previous": svc_before,
            "deletion": {
                "acknowledged": True,
                "status": "deleted",
                "service_id": service_id,
                "updated_at": now
            },
            "meta": {"latency_ms": latency_ms}
        }

    status_code = "CONFLICT"
    latency_ms = int((time.time() - t0) * 1000)
    return _err("CONFLICT", "Service cannot be deleted due to its current state.", status=cur)

def service_restart(service_id, railway_environment_id, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "service_restart"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    if not isinstance(service_id, str) or not service_id.strip() or not re.match(r"^rwy_svc_[0-9A-Z]+$", service_id.strip()):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is missing or malformed.", field="service_id")
    service_id = service_id.strip()

    if not isinstance(railway_environment_id, str) or not railway_environment_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "railway_environment_id is missing or invalid.", field="railway_environment_id")
    railway_environment_id = railway_environment_id.strip()

    services = _load("services.json")
    projects = _load("projects.json")
    deployments = _load("deployments.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list):
        services = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(deployments, list):
        deployments = []
    if not isinstance(accounts, list):
        accounts = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    # Validate environment exists on the parent project (cached environments list)
    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == svc.get("project_id"):
            prj = p
            break
    if prj is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Owning project does not exist.", service_id=service_id)

    envs = prj.get("environments")
    if not isinstance(envs, list):
        envs = []
    env_ok = any(isinstance(e, dict) and e.get("railway_environment_id") == railway_environment_id for e in envs)
    if not env_ok:
        _append_request_log("NOT_FOUND", account_id=prj.get("account_id"), service_id=service_id, extra={"railway_environment_id": railway_environment_id})
        return _err("NOT_FOUND", "Environment does not exist for this service's project.", railway_environment_id=railway_environment_id)

    account_id = prj.get("account_id")
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id, service_id=service_id)
        return _err("UNAUTHORIZED", "You don’t have permission to restart the service in that environment (no active token).", account_id=account_id)

    if svc.get("status") == "deleted":
        _append_request_log("INVALID_TRANSITION", account_id=account_id, service_id=service_id)
        return _err("INVALID_TRANSITION", "Cannot restart a deleted service.", service_id=service_id)

    if svc.get("status") == "deleting":
        _append_request_log("INVALID_TRANSITION", account_id=account_id, service_id=service_id)
        return _err("INVALID_TRANSITION", "Cannot restart a service that is deleting.", service_id=service_id)

    # Enforce at most 1 active deployment per (service, env) in queued/building/deploying
    active_states = {"queued", "building", "deploying"}
    for d in deployments:
        if not isinstance(d, dict):
            continue
        if d.get("service_id") == service_id and d.get("railway_environment_id") == railway_environment_id and d.get("status") in active_states:
            _append_request_log("CONFLICT", account_id=account_id, service_id=service_id, extra={"deployment_id": d.get("id")})
            return _err("CONFLICT", "An active deployment is already running for this service/environment.", service_id=service_id, railway_environment_id=railway_environment_id, active_deployment_id=d.get("id"))

    now = _now()

    # Create a new deployment row (restart triggers a new deployment event)
    dep_id = _gen_id("rwy_dep_")
    dep = {
        "id": dep_id,
        "service_id": service_id,
        "railway_environment_id": railway_environment_id,
        "railway_deployment_id": _gen_id("dep_"),  # upstream-like opaque id
        "trigger_reason": "manual",
        "commit_sha": None,
        "image_digest": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "logs": [{"ts": now, "stream": "system", "message": "Restart requested; deployment queued."}],
        "created_at": now,
        "updated_at": now,
    }
    deployments.append(dep)

    # Transition service to restarting (allowed from active/restarting per lifecycle)
    svc["status"] = "restarting"
    svc["updated_at"] = now
    services[svc_idx] = svc

    _save("deployments.json", deployments)
    _save("services.json", services)

    _append_request_log("OK", account_id=account_id, service_id=service_id, extra={"deployment_id": dep_id, "railway_environment_id": railway_environment_id})
    return {
        "service_id": service_id,
        "railway_environment_id": railway_environment_id,
        "status": "restarting",
        "deployment": {"id": dep_id, "status": dep.get("status"), "created_at": dep.get("created_at")},
    }

