            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "tcp_proxy_create"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    if not isinstance(service_id, str) or not service_id.strip() or not re.match(r"^rwy_svc_[0-9A-Z]+$", service_id.strip()):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is missing or malformed.", field="service_id")
    service_id = service_id.strip()

    if not isinstance(railway_environment_id, str) or not railway_environment_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "railway_environment_id is missing or invalid.", field="railway_environment_id")
    railway_environment_id = railway_environment_id.strip()

    if not isinstance(service_port, int) or not (1 <= service_port <= 65535):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_port must be an integer between 1 and 65535.", field="service_port")

    services = _load("services.json")
    projects = _load("projects.json")
    if not isinstance(services, list): services = []
    if not isinstance(projects, list): projects = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    if svc.get("status") == "deleted":
        _append_request_log("INVALID_TRANSITION", service_id=service_id)
        return _err("INVALID_TRANSITION", "Deleted services are immutable; cannot create TCP proxies.", service_id=service_id)

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not isinstance(proj, dict):
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Parent project does not exist for service.", service_id=service_id, project_id=svc.get("project_id"))

    envs = proj.get("environments")
    if not isinstance(envs, list) or not any(isinstance(e, dict) and e.get("railway_environment_id") == railway_environment_id for e in envs):
        _append_request_log("NOT_FOUND", account_id=proj.get("account_id"), service_id=service_id, extra={"railway_environment_id": railway_environment_id})
        return _err("NOT_FOUND", "Environment does not exist for this project.", railway_environment_id=railway_environment_id, project_id=proj.get("id"))

    proxies = svc.get("tcp_proxies")
    if not isinstance(proxies, list):
        proxies = []

    # enforce unique (service, env, external_port)
    # choose an external port in an unclaimed range (local simulation)
    used_ports = set()
    for p in proxies:
        if isinstance(p, dict) and p.get("railway_environment_id") == railway_environment_id and isinstance(p.get("external_port"), int):
            used_ports.add(p.get("external_port"))

    external_port = None
    for candidate in range(30000, 40000):
        if candidate not in used_ports:
            external_port = candidate
            break
    if external_port is None:
        _append_request_log("CONFLICT", account_id=proj.get("account_id"), service_id=service_id)
        return _err("CONFLICT", "No available external ports for TCP proxy in this environment.", railway_environment_id=railway_environment_id)

    tcp_proxy_id = _gen_id("rwy_tcp_")
    ts = _now()
    proxy = {
        "id": tcp_proxy_id,
        "railway_environment_id": railway_environment_id,
        "external_port": external_port,
        "service_port": service_port,
        "created_at": ts,
    }

    proxies.append(proxy)
    svc["tcp_proxies"] = proxies
    svc["updated_at"] = ts
    services[svc_idx] = svc
    _save("services.json", services)

    _append_request_log("OK", account_id=proj.get("account_id"), service_id=service_id, extra={"tcp_proxy_id": tcp_proxy_id})
    return {"service_id": service_id, "tcp_proxy": proxy}

