        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Project not found for service.", project_id=svc.get("project_id"))

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == proj.get("account_id")), None)
    if not acct:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized account context found for this service.")

    # Require active token to view variables (treat as protected)
    if acct.get("token_status") != "active" or not acct.get("api_token_ciphertext"):
        _log("error", account_id=acct.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API token configured for this account.", account_id=acct.get("id"))

    # Environment existence check under project
    envs = proj.get("environments")
    if not isinstance(envs, list) or not any(isinstance(e, dict) and e.get("railway_environment_id") == railway_environment_id for e in envs):
        _log("error", account_id=acct.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Environment not found for this project.", railway_environment_id=railway_environment_id)

    vars_arr = svc.get("variables")
    if not isinstance(vars_arr, list):
        vars_arr = []

    # Filter and return as {name,value}; do not return ciphertext
    out = []
    for v in vars_arr:
        if not isinstance(v, dict):
            continue
        if v.get("railway_environment_id") != railway_environment_id:
            continue
        name = v.get("key")
        if not isinstance(name, str):
            continue
        out.append({
            "name": name,
            "value": v.get("value"),  # may be absent; return None if not stored
            "is_secret": bool(v.get("is_secret", False)),
            "updated_by": v.get("updated_by"),
            "updated_at": v.get("updated_at"),
        })

    out.sort(key=lambda x: x.get("name") or "")
    _log("ok", account_id=acct.get("id"))
    return {
        "service_id": service_id,
        "railway_environment_id": railway_environment_id,
        "variables": out,
        "count": len(out),
    }

