        }
        if error_code:
            row["error_code"] = error_code
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate
    if not isinstance(service_id, str) or not re.match(r"^rwy_svc_[0-9A-HJKMNP-TV-Z]{10,}$", service_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "service_id is malformed.")
    if not isinstance(railway_environment_id, str) or not railway_environment_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "railway_environment_id is required.")
    if not isinstance(name, str) or len(name.strip()) < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if not isinstance(value, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "value must be a string.")

    key = name.strip()

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")

    svc = next((s for s in services if isinstance(s, dict) and s.get("id") == service_id), None)
    if not svc:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Service not found.", service_id=service_id)

    if svc.get("status") == "deleted":
        _log("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Service is deleted and cannot be modified.", service_id=service_id)

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not proj:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Project not found for service.", project_id=svc.get("project_id"))

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == proj.get("account_id")), None)
    if not acct:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized account context found for this service.")

    # Require active token to modify variables
    if acct.get("token_status") != "active" or not acct.get("api_token_ciphertext"):
        _log("error", account_id=acct.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API token configured for this account.", account_id=acct.get("id"))

    # Environment existence check under project
    envs = proj.get("environments")
    if not isinstance(envs, list) or not any(isinstance(e, dict) and e.get("railway_environment_id") == railway_environment_id for e in envs):
        _log("error", account_id=acct.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Environment not found for this project.", railway_environment_id=railway_environment_id)

    vars_arr = svc.get("variables")
    if not isinstance(vars_arr, list):
        vars_arr = []

    # Enforce uniqueness (railway_environment_id, key) within service
    matches = [i for i, v in enumerate(vars_arr) if isinstance(v, dict) and v.get("railway_environment_id") == railway_environment_id and v.get("key") == key]
    if len(matches) > 1:
        _log("error", account_id=acct.get("id"), error_code="CONFLICT")
        return _err("CONFLICT", "Multiple variables with the same key exist in this environment; manual repair required.", name=key)

    # Store ciphertext (do not store plaintext in value_ciphertext). Keep plain value in 'value' field for readback if present.
    value_ciphertext = "b64:" + base64.b64encode(value.encode("utf-8")).decode("ascii")

    updated_by = "mcp"
    entry = {
        "railway_environment_id": railway_environment_id,
        "key": key,
        "value_ciphertext": value_ciphertext,
        "value": value,
        "is_secret": True,
        "updated_by": updated_by,
        "updated_at": now,
    }

    if matches:
        vars_arr[matches[0]] = {**vars_arr[matches[0]], **entry}
    else:
        vars_arr.append(entry)

    svc["variables"] = vars_arr
    svc["updated_at"] = now
    _save("services.json", services)

    _log("ok", account_id=acct.get("id"))
    return {
        "service_id": service_id,
        "railway_environment_id": railway_environment_id,
        "variable": {
            "name": key,
            "value": value,
            "is_secret": True,
            "updated_by": updated_by,
            "updated_at": now,
        }
    }

