def variable_bulk_set(service_id, railway_environment_id, variables, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "variable_bulk_set"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation (pattern per tool schema)
    if not isinstance(service_id, str) or not re.match(r"^rwy_svc_[0-9A-HJKMNP-TV-Z]{10,}$", service_id or ""):
        _append_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is invalid.", field="service_id")
    if not isinstance(railway_environment_id, str) or not railway_environment_id.strip():
        _append_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "railway_environment_id is invalid.", field="railway_environment_id")
    railway_environment_id = railway_environment_id.strip()

    if not isinstance(variables, list) or len(variables) < 1:
        _append_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "variables must be a non-empty array.", field="variables")

    # Validate all entries before mutating (atomic per environment)
    parsed = []
    for idx, v in enumerate(variables):
        if not isinstance(v, dict):
            _append_log("VALIDATION_ERROR", service_id=service_id, extra={"index": idx})
            return _err("VALIDATION_ERROR", "Each variables item must be an object.", index=idx)
        if set(v.keys()) - {"name", "value"}:
            _append_log("VALIDATION_ERROR", service_id=service_id, extra={"index": idx, "extra_keys": sorted(set(v.keys()) - {"name", "value"})})
            return _err("VALIDATION_ERROR", "Unrecognized fields in variables item.", index=idx, fields=sorted(set(v.keys()) - {"name", "value"}))
        name = v.get("name")
        value = v.get("value")
        if not isinstance(name, str) or not name.strip():
            _append_log("VALIDATION_ERROR", service_id=service_id, extra={"index": idx})
            return _err("VALIDATION_ERROR", "Variable name is required and must be a non-empty string.", index=idx, field="name")
        if not isinstance(value, str):
            _append_log("VALIDATION_ERROR", service_id=service_id, extra={"index": idx})
            return _err("VALIDATION_ERROR", "Variable value must be a string.", index=idx, field="value")
        parsed.append((name.strip(), value))

    services = _load("services.json")
    projects = _load("projects.json")
    if not isinstance(services, list): services = []
    if not isinstance(projects, list): projects = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service not found.", service_id=service_id)

    if svc.get("status") == "deleted":
        _append_log("INVALID_TRANSITION", service_id=service_id)
        return _err("INVALID_TRANSITION", "Deleted services are immutable; cannot update variables.", service_id=service_id)

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == svc.get("project_id")), None)
    if not isinstance(proj, dict):
        _append_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Parent project not found for service.", service_id=service_id, project_id=svc.get("project_id"))

    envs = proj.get("environments")
    if not isinstance(envs, list) or not any(isinstance(e, dict) and e.get("railway_environment_id") == railway_environment_id for e in envs):
        _append_log("NOT_FOUND", account_id=proj.get("account_id"), service_id=service_id, extra={"railway_environment_id": railway_environment_id})
        return _err("NOT_FOUND", "Environment does not exist for this project.", railway_environment_id=railway_environment_id, project_id=proj.get("id"))

    # Apply upserts
    ts = _now()
    vars_arr = svc.get("variables")
    if not isinstance(vars_arr, list):
        vars_arr = []

    # index existing vars by (env,key)
    idx_by_key = {}
    for i, row in enumerate(vars_arr):
        if not isinstance(row, dict):
            continue
        ek = row.get("railway_environment_id")
        kk = row.get("key")
        if isinstance(ek, str) and isinstance(kk, str):
            idx_by_key[(ek, kk)] = i

    applied = []
    for name, value in parsed:
        k = (railway_environment_id, name)
        if k in idx_by_key:
            row = dict(vars_arr[idx_by_key[k]])
            row["value_ciphertext"] = "enc:" + value  # store non-plaintext representation
            row["updated_by"] = "variable_bulk_set"
            row["is_secret"] = bool(row.get("is_secret", False))
            vars_arr[idx_by_key[k]] = row
            applied.append(row)
        else:
            row = {
                "railway_environment_id": railway_environment_id,
                "key": name,
                "value_ciphertext": "enc:" + value,
                "is_secret": False,
                "updated_by": "variable_bulk_set",
            }
            vars_arr.append(row)
            idx_by_key[k] = len(vars_arr) - 1
            applied.append(row)

    # Ensure uniqueness within service for (env,key) (defensive)
    seen = set()
    for row in vars_arr:
        if not isinstance(row, dict):
            continue
        ek = row.get("railway_environment_id")
        kk = row.get("key")
        if isinstance(ek, str) and isinstance(kk, str):
            if (ek, kk) in seen:
                _append_log("CONFLICT", account_id=proj.get("account_id"), service_id=service_id)
                return _err("CONFLICT", "Duplicate variable keys detected for the same environment within the service.", railway_environment_id=ek, key=kk)
            seen.add((ek, kk))

    svc["variables"] = vars_arr
    svc["updated_at"] = ts
    services[svc_idx] = svc
    _save("services.json", services)

    _append_log("OK", account_id=proj.get("account_id"), service_id=service_id, extra={"count": len(applied), "railway_environment_id": railway_environment_id})
    return {"service_id": service_id, "railway_environment_id": railway_environment_id, "variables": applied, "count": len(applied)}

