    if prj is None:
        _append_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Owning project does not exist.", service_id=service_id)

    envs = prj.get("environments")
    if not isinstance(envs, list):
        envs = []
    env_ids = {e.get("railway_environment_id") for e in envs if isinstance(e, dict)}
    if from_railway_environment_id not in env_ids:
        _append_log("NOT_FOUND", account_id=prj.get("account_id"), service_id=service_id, extra={"from": from_railway_environment_id})
        return _err("NOT_FOUND", "Source environment does not exist for this project.", railway_environment_id=from_railway_environment_id)
    if to_railway_environment_id not in env_ids:
        _append_log("NOT_FOUND", account_id=prj.get("account_id"), service_id=service_id, extra={"to": to_railway_environment_id})
        return _err("NOT_FOUND", "Destination environment does not exist for this project.", railway_environment_id=to_railway_environment_id)

    account_id = prj.get("account_id")
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_log("UNAUTHORIZED", account_id=account_id, service_id=service_id)
        return _err("UNAUTHORIZED", "You don’t have access to copy variables (no active token).", account_id=account_id)

    vars_arr = svc.get("variables")
    if not isinstance(vars_arr, list):
        vars_arr = []

    src_vars = [v for v in vars_arr if isinstance(v, dict) and v.get("railway_environment_id") == from_railway_environment_id and isinstance(v.get("key"), str)]
    # Map dest existing keys
    dest_index = {}
    for idx, v in enumerate(vars_arr):
        if not isinstance(v, dict):
            continue
        if v.get("railway_environment_id") == to_railway_environment_id and isinstance(v.get("key"), str):
            dest_index[v.get("key")] = idx

    created = 0
    updated = 0
    skipped = 0
    changes = []

    now = _now()
    # Perform updates atomically: build new array
    new_vars = list(vars_arr)
    for sv in src_vars:
        key = sv.get("key")
        if key in dest_index:
            if not overwrite:
                skipped += 1
                continue
            di = dest_index[key]
            dv = dict(new_vars[di]) if isinstance(new_vars[di], dict) else {}
            dv["value_ciphertext"] = sv.get("value_ciphertext")
            dv["is_secret"] = sv.get("is_secret")
            dv["updated_by"] = "variable_copy"
            dv["updated_at"] = now
            new_vars[di] = dv
            updated += 1
            changes.append({"key": key, "action": "updated"})
        else:
            nv = {
                "railway_environment_id": to_railway_environment_id,
                "key": key,
                "value_ciphertext": sv.get("value_ciphertext"),
                "is_secret": sv.get("is_secret"),
                "updated_by": "variable_copy",
                "updated_at": now,
            }
            new_vars.append(nv)
            created += 1
            changes.append({"key": key, "action": "created"})

    svc["variables"] = new_vars
    svc["updated_at"] = now
    services[svc_idx] = svc
    _save("services.json", services)

    _append_log("OK", account_id=account_id, service_id=service_id, extra={"created": created, "updated": updated, "skipped": skipped, "from": from_railway_environment_id, "to": to_railway_environment_id})
    return {
        "service_id": service_id,
        "from_railway_environment_id": from_railway_environment_id,
        "to_railway_environment_id": to_railway_environment_id,
        "overwrite": overwrite,
        "summary": {"created": created, "updated": updated, "skipped": skipped, "total_source": len(src_vars)},
        "changes": changes,
    }

def configure_api_token(account_id, api_token, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "configure_api_token"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, message=None, credential_id=None, account_id=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "message": message,
            "credential_id": credential_id,
            "account_id": account_id,
            "project_id": None,
            "service_id": None,
            "extra": extra or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(account_id, str) or not re.match(r"^rwy_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        _append_log("error", "VALIDATION_ERROR: invalid account_id")
        return _err("VALIDATION_ERROR", "account_id is invalid.")
    if not isinstance(api_token, str) or len(api_token) < 10:
        _append_log("error", "VALIDATION_ERROR: api_token too short", account_id=account_id)
        return _err("VALIDATION_ERROR", "api_token must be at least 10 characters long.")

    accounts = _load("railway_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _append_log("error", "NOT_FOUND: account not found", account_id=account_id)
        return _err("NOT_FOUND", "Account not found.")

    # Simulated upstream token check: reject clearly invalid placeholders (still offline).
    low = api_token.strip().lower()
    if low in ("invalid", "revoked", "null", "none") or api_token.strip() == "":
        _append_log("error", "UNAUTHORIZED: token rejected", account_id=account_id)
        return _err("UNAUTHORIZED", "Railway rejected the provided API token.")

    # Enforce lifecycle transitions: unset->active, active->active, revoked->active allowed
    allowed = {
        "unset": {"active"},
        "active": {"revoked", "active"},
        "revoked": {"active"}
    }
    cur = acct.get("token_status")
    if cur not in allowed or "active" not in allowed[cur]:
        _append_log("error", "INVALID_TRANSITION: cannot activate token from current state", account_id=account_id, extra={"current": cur})
        return _err("INVALID_TRANSITION", "Cannot activate token from current status.", current=cur, requested="active")

    # Must not store plaintext: store a ciphertext placeholder only
    last4 = api_token[-4:] if len(api_token) >= 4 else api_token
    ts = _now()
    acct["api_token_ciphertext"] = f"cipher:v1:len:{len(api_token)}"
    acct["api_token_last4"] = last4
    acct["token_status"] = "active"
    acct["updated_at"] = ts
    if not acct.get("created_at"):
        acct["created_at"] = ts

    # Constraints: active implies ciphertext not null
    if not acct.get("api_token_ciphertext"):
        _append_log("error", "CONFLICT: active token missing ciphertext", account_id=account_id)
        return _err("CONFLICT", "Token storage constraint violated.")

    _save("railway_accounts.json", accounts)

    _append_log("ok", account_id=account_id, extra={"token_status": "active", "api_token_last4": last4})
    return {
        "account_id": account_id,
        "token_status": "active",
        "api_token_last4": last4,
        "updated_at": ts
    }

