        _append_log("error", "VALIDATION_ERROR: invalid project_id")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if railway_environment_id is not None and (not isinstance(railway_environment_id, str) or not railway_environment_id.strip()):
        _append_log("error", "VALIDATION_ERROR: invalid railway_environment_id", project_id=project_id)
        return _err("VALIDATION_ERROR", "railway_environment_id is invalid.")

    accounts = _load("railway_accounts.json")
    projects = _load("projects.json")
    services = _load("services.json")

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj:
        _append_log("error", "NOT_FOUND: project not found", project_id=project_id)
        return _err("NOT_FOUND", "Project not found.")

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == prj.get("account_id")), None)
