    envs = prj.get("environments") if isinstance(prj.get("environments"), list) else []
    if railway_environment_id is not None:
        if not any(isinstance(e, dict) and e.get("railway_environment_id") == railway_environment_id for e in envs):
            _append_log("error", "NOT_FOUND: environment not found in project", account_id=acct.get("id"), project_id=project_id)
            return _err("NOT_FOUND", "Environment not found in project.")

    # Collect volumes across services in the project
    out = []
    for s in services:
        if not isinstance(s, dict):
            continue
        if s.get("project_id") != project_id:
            continue
        vols = s.get("volumes")
        if not isinstance(vols, list):
            continue
        for v in vols:
            if not isinstance(v, dict):
                continue
            if railway_environment_id is not None and v.get("railway_environment_id") != railway_environment_id:
                continue
            out.append({
                "service_id": s.get("id"),
                "service_name": s.get("name"),
                "railway_service_id": s.get("railway_service_id"),
                "railway_volume_id": v.get("railway_volume_id"),
                "name": v.get("name"),
                "mount_path": v.get("mount_path"),
                "size_gb": v.get("size_gb"),
                "railway_environment_id": v.get("railway_environment_id"),
                "status": v.get("status")
            })

    _append_log("ok", account_id=acct.get("id"), project_id=project_id, extra={"railway_environment_id": railway_environment_id, "count": len(out)})
    return {
        "project_id": project_id,
        "railway_environment_id": railway_environment_id,
        "volumes": out,
        "count": len(out)
    }

def volume_create(service_id, body, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _gen_ulid_like(prefix):
        # Deterministic-enough offline id: prefix + UTC timestamp + random-ish bits
        import secrets
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        rnd = secrets.token_hex(6)
        return f"{prefix}{ts}{rnd}"

    def _log_call(endpoint, status, credential_id=None, error_code=None, meta=None, started_at=None):
        reqs = _load("request_logs.json")
        if started_at is None:
            started_at = datetime.datetime.utcnow()
        latency_ms = int((datetime.datetime.utcnow() - started_at).total_seconds() * 1000)
        row = {
            "id": _gen_ulid_like("req_"),
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _check_rate_limit(account_id, endpoint, started_at):
        # Simple global per-account rate limit: 120 req/min across all endpoints.
        # Enforced via request_logs.json if present.
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return None
        reqs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reqs:
            if r.get("endpoint") and r.get("ts") and r.get("meta") and isinstance(r["meta"], dict):
                if r["meta"].get("account_id") != account_id:
                    continue
                try:
                    ts = r.get("ts")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        ts_dt = datetime.datetime.fromisoformat(ts[:-1])
                    else:
                        ts_dt = datetime.datetime.fromisoformat(ts)
                except Exception:
                    continue
                if ts_dt >= window_start:
                    cnt += 1
        if cnt >= 120:
            _log_call(endpoint, "error", None, "RATE_LIMIT", meta={"account_id": account_id}, started_at=started_at)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    started_at = datetime.datetime.utcnow()
    endpoint = "volume_create"

    # Validate input
    if not _is_str(service_id):
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "service_id must be a non-empty string.")
    if not isinstance(body, dict):
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "body must be an object.")
    for k in ("name", "mount_path", "size_gb"):
        if k not in body:
            _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id}, started_at=started_at)
            return _err("VALIDATION_ERROR", f"Missing required field: body.{k}")

    name = body.get("name")
    mount_path = body.get("mount_path")
    size_gb = body.get("size_gb")

    if not _is_str(name):
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "body.name must be a non-empty string.")
    if not _is_str(mount_path) or not mount_path.startswith("/") or "//" in mount_path:
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "body.mount_path must be an absolute path (e.g. /data).")
    if not isinstance(size_gb, int):
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "body.size_gb must be an integer.")
    if size_gb < 1 or size_gb > 10240:
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "body.size_gb must be between 1 and 10240 (GiB).")

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")

    svc = next((s for s in services if s.get("id") == service_id), None)
    if not svc:
        _log_call(endpoint, "error", None, "NOT_FOUND", meta={"service_id": service_id}, started_at=started_at)
        return _err("NOT_FOUND", "Service not found.")

    # Authorization: require the owning account has an active token
    proj = next((p for p in projects if p.get("id") == svc.get("project_id")), None)
    if not proj:
        _log_call(endpoint, "error", None, "NOT_FOUND", meta={"service_id": service_id}, started_at=started_at)
        return _err("NOT_FOUND", "Parent project not found for service.")
    acct_id = proj.get("account_id")
    acct = next((a for a in accounts if a.get("id") == acct_id), None)
    if not acct:
        _log_call(endpoint, "error", None, "NOT_FOUND", meta={"service_id": service_id}, started_at=started_at)
        return _err("NOT_FOUND", "Account not found for service.")
    if acct.get("token_status") != "active":
        _log_call(endpoint, "error", None, "UNAUTHORIZED", meta={"account_id": acct_id}, started_at=started_at)
        return _err("UNAUTHORIZED", "No active API token configured for this account.")

    rl_err = _check_rate_limit(acct_id, endpoint, started_at)
    if rl_err:
        return rl_err

    # Reject mutations on deleted services
    if svc.get("status") == "deleted":
        _log_call(endpoint, "error", None, "CONFLICT", meta={"service_id": service_id, "account_id": acct_id}, started_at=started_at)
        return _err("CONFLICT", "Service is deleted and is immutable.")

    vols = svc.get("volumes")
    if not isinstance(vols, list):
        vols = []
        svc["volumes"] = vols

    # Enforce unique mount_path per (service, environment).
    env_id = body.get("railway_environment_id")  # optional in tool; if absent, treat as "default"/None-scoped.
    # If project has environments, default to the one marked is_default.
    if not _is_str(env_id):
        env_id = None
        envs = proj.get("environments") if isinstance(proj.get("environments"), list) else []
        default_env = next((e for e in envs if isinstance(e, dict) and e.get("is_default") is True and _is_str(e.get("railway_environment_id"))), None)
        if default_env:
            env_id = default_env.get("railway_environment_id")
    if not _is_str(env_id):
        # If we still don't know environment, require it to satisfy uniqueness rule.
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"service_id": service_id, "account_id": acct_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "Unable to resolve an environment for the volume. Provide a project default environment via project sync or include railway_environment_id in the body.")

    for v in vols:
        if not isinstance(v, dict):
            continue
        if v.get("railway_environment_id") == env_id and v.get("mount_path") == mount_path and v.get("status") != "deleted":
            _log_call(endpoint, "error", None, "CONFLICT", meta={"service_id": service_id, "account_id": acct_id}, started_at=started_at)
            return _err("CONFLICT", "A volume with this mount_path already exists for this environment.")

    vol_id = _gen_ulid_like("rwy_vol_")
    new_vol = {
        "railway_volume_id": vol_id,
        "name": name,
        "mount_path": mount_path,
        "size_gb": size_gb,
        "railway_environment_id": env_id,
        "status": "provisioning",
    }
    vols.append(new_vol)
    svc["updated_at"] = _now()

    # Persist
    for i, s in enumerate(services):
        if s.get("id") == service_id:
            services[i] = svc
            break
    _save("services.json", services)

    # Return created volume
    _log_call(endpoint, "ok", None, None, meta={"account_id": acct_id, "service_id": service_id}, started_at=started_at)
    return {"volume": new_vol}

def volume_update(service_id, volume_id, body, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "volume_update"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is missing or invalid.", field="service_id")
    if not isinstance(volume_id, str) or not volume_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "volume_id is missing or invalid.", field="volume_id")
    if not isinstance(body, dict):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "body must be an object.", field="body")

    service_id = service_id.strip()
    volume_id = volume_id.strip()

    allowed = {"name", "mount_path", "size_gb"}
    extra = set(body.keys()) - allowed
    if extra:
        _append_request_log("VALIDATION_ERROR", service_id=service_id, extra={"extra_keys": sorted(extra)})
        return _err("VALIDATION_ERROR", "Unrecognized fields in body.", fields=sorted(extra))

    if not any(k in body for k in allowed):
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "body contains no supported fields to update.", field="body")

    if "mount_path" in body:
        mp = body.get("mount_path")
        if not isinstance(mp, str) or not mp.startswith("/") or "//" in mp or len(mp) < 2:
            _append_request_log("VALIDATION_ERROR", service_id=service_id)
            return _err("VALIDATION_ERROR", "mount_path must be an absolute path like /data.", field="body.mount_path")

    if "size_gb" in body:
        sg = body.get("size_gb")
        if not isinstance(sg, int) or not (1 <= sg <= 10240):
            _append_request_log("VALIDATION_ERROR", service_id=service_id)
            return _err("VALIDATION_ERROR", "size_gb must be an integer between 1 and 10240.", field="body.size_gb")

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list):
        services = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(accounts, list):
        accounts = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    if svc.get("status") == "deleted":
        _append_request_log("INVALID_TRANSITION", service_id=service_id)
        return _err("INVALID_TRANSITION", "Deleted services are immutable; volume updates are not allowed.", service_id=service_id)

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == svc.get("project_id"):
            prj = p
            break
    account_id = prj.get("account_id") if isinstance(prj, dict) else None
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id, service_id=service_id)
        return _err("UNAUTHORIZED", "You don’t have permission to modify volumes (no active token).", account_id=account_id)

    vols = svc.get("volumes")
    if not isinstance(vols, list):
        vols = []

    vol_idx = None
    vol = None
    for j, v in enumerate(vols):
        if isinstance(v, dict) and (v.get("railway_volume_id") == volume_id or v.get("id") == volume_id):
            vol_idx = j
            vol = v
            break
    if vol is None:
        _append_request_log("NOT_FOUND", account_id=account_id, service_id=service_id, extra={"volume_id": volume_id})
        return _err("NOT_FOUND", "Volume does not exist for this service.", service_id=service_id, volume_id=volume_id)

    # Enforce unique mount_path per (service, environment)
    if "mount_path" in body:
        new_mp = body.get("mount_path")
        env_id = vol.get("railway_environment_id")
        for k, ov in enumerate(vols):
            if k == vol_idx or not isinstance(ov, dict):
                continue
            if ov.get("railway_environment_id") == env_id and ov.get("mount_path") == new_mp:
                _append_request_log("CONFLICT", account_id=account_id, service_id=service_id, extra={"mount_path": new_mp, "railway_environment_id": env_id})
                return _err("CONFLICT", "mount_path must be unique per environment for this service.", mount_path=new_mp, railway_environment_id=env_id)

    now = _now()
    new_vol = dict(vol)
    if "name" in body:
        nm = body.get("name")
        if nm is not None and not isinstance(nm, str):
            _append_request_log("VALIDATION_ERROR", account_id=account_id, service_id=service_id)
            return _err("VALIDATION_ERROR", "name must be a string.", field="body.name")
        new_vol["name"] = nm
    if "mount_path" in body:
        new_vol["mount_path"] = body.get("mount_path")
    if "size_gb" in body:
        new_vol["size_gb"] = body.get("size_gb")
    new_vol["updated_at"] = now

    vols[vol_idx] = new_vol
    svc["volumes"] = vols
    svc["updated_at"] = now
    services[svc_idx] = svc
    _save("services.json", services)

    _append_request_log("OK", account_id=account_id, service_id=service_id, extra={"volume_id": volume_id})
    return {"service_id": service_id, "volume": new_vol}

def volume_delete(service_id, volume_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "volume_delete"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, service_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
            "service_id": service_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(service_id, str) or not service_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "service_id is missing or invalid.", field="service_id")
    if not isinstance(volume_id, str) or not volume_id.strip():
        _append_request_log("VALIDATION_ERROR", service_id=service_id)
        return _err("VALIDATION_ERROR", "volume_id is missing or invalid.", field="volume_id")

    service_id = service_id.strip()
    volume_id = volume_id.strip()

    services = _load("services.json")
    projects = _load("projects.json")
    accounts = _load("railway_accounts.json")
    if not isinstance(services, list):
        services = []
    if not isinstance(projects, list):
        projects = []
    if not isinstance(accounts, list):
        accounts = []

    svc_idx = None
    svc = None
    for i, s in enumerate(services):
        if isinstance(s, dict) and s.get("id") == service_id:
            svc = s
            svc_idx = i
            break
    if svc is None:
        _append_request_log("NOT_FOUND", service_id=service_id)
        return _err("NOT_FOUND", "Service does not exist.", service_id=service_id)

    if svc.get("status") == "deleted":
        _append_request_log("INVALID_TRANSITION", service_id=service_id)
        return _err("INVALID_TRANSITION", "Deleted services are immutable; volume deletions are not allowed.", service_id=service_id)

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == svc.get("project_id"):
            prj = p
            break
    account_id = prj.get("account_id") if isinstance(prj, dict) else None
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id, service_id=service_id)
        return _err("UNAUTHORIZED", "You don’t have permission to modify volumes (no active token).", account_id=account_id)

    vols = svc.get("volumes")
    if not isinstance(vols, list):
        vols = []

    vol_idx = None
    vol = None
    for j, v in enumerate(vols):
        if isinstance(v, dict) and (v.get("railway_volume_id") == volume_id or v.get("id") == volume_id):
            vol_idx = j
            vol = v
            break
    if vol is None:
        _append_request_log("NOT_FOUND", account_id=account_id, service_id=service_id, extra={"volume_id": volume_id})
        return _err("NOT_FOUND", "Volume does not exist for this service.", service_id=service_id, volume_id=volume_id)

    # Block deletion if provisioning/resizing/etc.
    status = vol.get("status")
    if isinstance(status, str) and status.lower() in {"provisioning", "resizing", "migrating", "attaching", "detaching"}:
        _append_request_log("CONFLICT", account_id=account_id, service_id=service_id, extra={"status": status, "volume_id": volume_id})
        return _err("CONFLICT", "Volume cannot be deleted while an attachment/migration operation is in progress.", volume_id=volume_id, status=status)

    removed = vols.pop(vol_idx)
    now = _now()
    svc["volumes"] = vols
    svc["updated_at"] = now
    services[svc_idx] = svc
    _save("services.json", services)

    _append_request_log("OK", account_id=account_id, service_id=service_id, extra={"volume_id": volume_id})
    return {"service_id": service_id, "deleted": True, "volume": removed}

def template_list(account_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _gen_ulid_like(prefix):
        import secrets
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        rnd = secrets.token_hex(6)
        return f"{prefix}{ts}{rnd}"

    def _log_call(endpoint, status, credential_id=None, error_code=None, meta=None, started_at=None):
        reqs = _load("request_logs.json")
        if started_at is None:
            started_at = datetime.datetime.utcnow()
        latency_ms = int((datetime.datetime.utcnow() - started_at).total_seconds() * 1000)
        row = {
            "id": _gen_ulid_like("req_"),
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _check_rate_limit(account_id, endpoint, started_at):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return None
        reqs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reqs:
            if r.get("ts") and r.get("meta") and isinstance(r["meta"], dict) and r["meta"].get("account_id") == account_id:
                try:
                    ts = r.get("ts")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        ts_dt = datetime.datetime.fromisoformat(ts[:-1])
                    else:
                        ts_dt = datetime.datetime.fromisoformat(ts)
                except Exception:
                    continue
                if ts_dt >= window_start:
                    cnt += 1
        if cnt >= 120:
            _log_call(endpoint, "error", None, "RATE_LIMIT", meta={"account_id": account_id}, started_at=started_at)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
        return None

    def _decode_cursor(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj:
                return None
            off = obj["offset"]
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    started_at = datetime.datetime.utcnow()
    endpoint = "template_list"

    if not _is_str(account_id):
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"account_id": account_id}, started_at=started_at)
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit <= 0 or limit > 200:
        _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"account_id": account_id, "limit": limit}, started_at=started_at)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    offset = 0
    if cursor is not None:
        if not _is_str(cursor):
            _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"account_id": account_id}, started_at=started_at)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        off = _decode_cursor(cursor)
        if off is None:
            _log_call(endpoint, "error", None, "VALIDATION_ERROR", meta={"account_id": account_id}, started_at=started_at)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        offset = off

    accounts = _load("railway_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log_call(endpoint, "error", None, "NOT_FOUND", meta={"account_id": account_id}, started_at=started_at)
        return _err("NOT_FOUND", "Account not found.")

    # Authorization: require account token active to access catalog
    if acct.get("token_status") != "active":
        _log_call(endpoint, "error", None, "UNAUTHORIZED", meta={"account_id": account_id}, started_at=started_at)
        return _err("UNAUTHORIZED", "No active API token configured for this account.")

    rl_err = _check_rate_limit(account_id, endpoint, started_at)
    if rl_err:
        return rl_err

    catalog = _load("templates_and_db_types.json")
    snap = next((c for c in catalog if c.get("account_id") == account_id), None)
    if not snap:
        # Treat missing snapshot as unauthorized access to catalog per tool description / business rule
        _log_call(endpoint, "error", None, "UNAUTHORIZED", meta={"account_id": account_id}, started_at=started_at)
        return _err("UNAUTHORIZED", "Catalog snapshot not available for this account.")

    templates = snap.get("templates")
    if not isinstance(templates, list):
        templates = []

    # Stable ordering by name then id
    def _key(t):
        if not isinstance(t, dict):
            return ("", "")
        return (str(t.get("name") or ""), str(t.get("railway_template_id") or ""))
    templates_sorted = sorted([t for t in templates if isinstance(t, dict)], key=_key)

    total = len(templates_sorted)
    page = templates_sorted[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log_call(endpoint, "ok", None, None, meta={"account_id": account_id}, started_at=started_at)
    return {
        "templates": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

def template_deploy(account_id, template_id, body, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "template_deploy"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    def _append_request_log(status, account_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(acct_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        window_s = 60
        limit = 120
        now_dt = datetime.datetime.fromisoformat(_now().replace("Z", "+00:00"))
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if acct_id is not None and r.get("account_id") != acct_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if (now_dt - dt).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=limit, window_seconds=window_s)
        return None

    if not isinstance(account_id, str) or not account_id.strip():
        _append_request_log("VALIDATION_ERROR", account_id=account_id)
        return _err("VALIDATION_ERROR", "account_id is required and must be a non-empty string.", field="account_id")
    if not isinstance(template_id, str) or not template_id.strip():
        _append_request_log("VALIDATION_ERROR", account_id=account_id)
        return _err("VALIDATION_ERROR", "template_id is required and must be a non-empty string.", field="template_id")
    if not isinstance(body, dict):
        _append_request_log("VALIDATION_ERROR", account_id=account_id)
        return _err("VALIDATION_ERROR", "body must be an object.", field="body")

    account_id = account_id.strip()
    template_id = template_id.strip()

    allowed_body_keys = {"project_name", "service_name", "environment_name", "variables"}
    extra_keys = set(body.keys()) - allowed_body_keys
    if extra_keys:
        _append_request_log("VALIDATION_ERROR", account_id=account_id, extra={"extra_keys": sorted(extra_keys)})
        return _err("VALIDATION_ERROR", "Unrecognized fields in body.", fields=sorted(extra_keys))

    pn = body.get("project_name")
    if not isinstance(pn, str) or not pn.strip():
        _append_request_log("VALIDATION_ERROR", account_id=account_id)
        return _err("VALIDATION_ERROR", "body.project_name is required and must be a non-empty string.", field="body.project_name")
    project_name = pn.strip()

    variables = body.get("variables")
    if variables is not None:
        if not isinstance(variables, list):
            _append_request_log("VALIDATION_ERROR", account_id=account_id)
            return _err("VALIDATION_ERROR", "body.variables must be an array when provided.", field="body.variables")
        for i, v in enumerate(variables):
            if not isinstance(v, dict) or set(v.keys()) != {"key", "value"}:
                _append_request_log("VALIDATION_ERROR", account_id=account_id, extra={"index": i})
                return _err("VALIDATION_ERROR", "Each variables entry must be an object with {key, value}.", field=f"body.variables[{i}]")
            if not isinstance(v.get("key"), str) or not v.get("key").strip():
                _append_request_log("VALIDATION_ERROR", account_id=account_id, extra={"index": i})
                return _err("VALIDATION_ERROR", "Variable key must be a non-empty string.", field=f"body.variables[{i}].key")
            if not isinstance(v.get("value"), str):
                _append_request_log("VALIDATION_ERROR", account_id=account_id, extra={"index": i})
                return _err("VALIDATION_ERROR", "Variable value must be a string.", field=f"body.variables[{i}].value")

    # rate limit
    rl = _rate_limit_check(account_id)
    if rl:
        _append_request_log("RATE_LIMIT", account_id=account_id)
        return rl

    accounts = _load("railway_accounts.json")
    catalogs = _load("templates_and_db_types.json")
    if not isinstance(accounts, list):
        accounts = []
    if not isinstance(catalogs, list):
        catalogs = []

    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        _append_request_log("NOT_FOUND", account_id=account_id)
        return _err("NOT_FOUND", "Account does not exist.", account_id=account_id)

    # IMPORTANT: do not reject because this specific account's token might be revoked/unset;
    # resolve a working authenticated context across the store (ambient server auth).
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id)
        return _err("UNAUTHORIZED", "Account is not authorized to deploy templates (no active token available).", account_id=account_id)

    # Find a catalog snapshot for this account; if absent, allow searching any catalog snapshot that contains the template.
    snapshot = None
    for c in catalogs:
        if isinstance(c, dict) and c.get("account_id") == account_id:
            snapshot = c
            break
    if snapshot is None:
        for c in catalogs:
            if not isinstance(c, dict):
                continue
            tpls = c.get("templates")
            if isinstance(tpls, list) and any(isinstance(t, dict) and t.get("railway_template_id") == template_id for t in tpls):
                snapshot = c
                break
    if snapshot is None:
        _append_request_log("NOT_FOUND", account_id=account_id, extra={"template_id": template_id})
        return _err("NOT_FOUND", "Template catalog snapshot not found for this account.", account_id=account_id)

    templates = snapshot.get("templates")
    if not isinstance(templates, list):
        templates = []
    tpl = None
    for t in templates:
        if isinstance(t, dict) and t.get("railway_template_id") == template_id:
            tpl = t
            break
    if tpl is None:
        _append_request_log("NOT_FOUND", account_id=account_id, extra={"template_id": template_id})
        return _err("NOT_FOUND", "Template does not exist in the catalog.", template_id=template_id)

    workflows = snapshot.get("template_workflows")
    if not isinstance(workflows, list):
        workflows = []

    now = _now()
    wf_id = _gen_id("rwy_wf_")

    # create workflow execution
    wf = {
        "railway_workflow_id": wf_id,
        "railway_template_id": template_id,
        "project_railway_id": _gen_id("prj_"),
        "status": "queued",
        "started_at": now,
        "finished_at": None,
        "output_service_railway_ids": [],
    }
    workflows.append(wf)
    snapshot["template_workflows"] = workflows
    snapshot["updated_at"] = now

    # Persist the modified snapshot back into the catalogs list
    for i, c in enumerate(catalogs):
        if isinstance(c, dict) and c.get("id") == snapshot.get("id"):
            catalogs[i] = snapshot
            break
    _save("templates_and_db_types.json", catalogs)

    _append_request_log("OK", account_id=account_id, extra={"workflow_id": wf_id, "template_id": template_id, "project_name": project_name})
    return {
        "account_id": account_id,
        "template_id": template_id,
        "workflow_id": wf_id,
        "status": wf.get("status"),
        "started_at": wf.get("started_at"),
    }

def template_get_workflow_status(account_id, workflow_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0271000" if __import__("os").path.isdir("./environment_mix/0271000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "template_get_workflow_status"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, account_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account_id,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(acct_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        window_s = 60
        limit = 240
        now_dt = datetime.datetime.fromisoformat(_now().replace("Z", "+00:00"))
        cnt = 0
        for r in reversed(logs[-8000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if acct_id is not None and r.get("account_id") != acct_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if (now_dt - dt).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=limit, window_seconds=window_s)
        return None

    if not isinstance(account_id, str) or not account_id.strip():
        _append_request_log("VALIDATION_ERROR", account_id=account_id)
        return _err("VALIDATION_ERROR", "account_id is required and must be a non-empty string.", field="account_id")
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        _append_request_log("VALIDATION_ERROR", account_id=account_id)
        return _err("VALIDATION_ERROR", "workflow_id is required and must be a non-empty string.", field="workflow_id")

    account_id = account_id.strip()
    workflow_id = workflow_id.strip()

    rl = _rate_limit_check(account_id)
    if rl:
        _append_request_log("RATE_LIMIT", account_id=account_id)
        return rl

    accounts = _load("railway_accounts.json")
    catalogs = _load("templates_and_db_types.json")
    if not isinstance(accounts, list):
        accounts = []
    if not isinstance(catalogs, list):
        catalogs = []

    acct_exists = any(isinstance(a, dict) and a.get("id") == account_id for a in accounts)
    if not acct_exists:
        _append_request_log("NOT_FOUND", account_id=account_id)
        return _err("NOT_FOUND", "Account does not exist.", account_id=account_id)

    # Resolve a working authorized context across the store (ambient auth): require at least one active token somewhere.
    any_active = any(isinstance(a, dict) and a.get("token_status") == "active" for a in accounts)
    if not any_active:
        _append_request_log("UNAUTHORIZED", account_id=account_id)
        return _err("UNAUTHORIZED", "You can’t access workflows (no active token available).", account_id=account_id)

    # Find workflow in this account's snapshots; if not present, it's NOT_FOUND for the account.
    found = None
    found_snapshot_id = None
    for c in catalogs:
        if not isinstance(c, dict) or c.get("account_id") != account_id:
            continue
        wfs = c.get("template_workflows")
        if not isinstance(wfs, list):
            continue
        for w in wfs:
            if isinstance(w, dict) and w.get("railway_workflow_id") == workflow_id:
                found = w
                found_snapshot_id = c.get("id")
                break
        if found:
            break

    if found is None:
        _append_request_log("NOT_FOUND", account_id=account_id, extra={"workflow_id": workflow_id})
        return _err("NOT_FOUND", "workflow_id is unknown for the account.", account_id=account_id, workflow_id=workflow_id)

    # Enforce terminal rule: if succeeded, output_service_railway_ids must be present
    terminal = {"succeeded", "failed", "cancelled"}
    st = found.get("status")
    if st in terminal and st == "succeeded":
        out = found.get("output_service_railway_ids")
        if not isinstance(out, list) or len(out) == 0:
            # Data integrity issue, but return as conflict-like validation: use CONFLICT per allowed codes.
            _append_request_log("CONFLICT", account_id=account_id, extra={"workflow_id": workflow_id})
            return _err("CONFLICT", "Succeeded workflows must include output_service_railway_ids.", workflow_id=workflow_id)

    _append_request_log("OK", account_id=account_id, extra={"workflow_id": workflow_id, "status": st})
    return {
        "account_id": account_id,
        "workflow": {
            "railway_workflow_id": found.get("railway_workflow_id"),
            "railway_template_id": found.get("railway_template_id"),
            "project_railway_id": found.get("project_railway_id"),
            "status": found.get("status"),
            "started_at": found.get("started_at"),
            "finished_at": found.get("finished_at"),
            "output_service_railway_ids": found.get("output_service_railway_ids"),
            "catalog_snapshot_id": found_snapshot_id,
        },
    }
